"use client"

import * as React from "react"
import { Slot } from "radix-ui"

import { motionIsOff } from "@/hooks/use-live-motion"
import { useMergedRef } from "@/lib/ink/react"
import {
  CONFETTI_COLORS,
  CONFETTI_KINDS,
  STEP_MS,
  confettiPiece,
  simulate,
  type ConfettiColor,
  type ConfettiKind,
} from "@/lib/ink/recipes/confetti-ink"
import { cn } from "@/lib/utils"

type Origin = Element | { x: number; y: number } | { clientX: number; clientY: number } | null | undefined

interface ConfettiOptions {
  origin?: Origin
  count?: number
  spread?: number
  angle?: number
  velocity?: number
  gravity?: number
  drift?: number
  duration?: number
  colors?: readonly ConfettiColor[]
  shapes?: readonly ConfettiKind[]
  scalar?: number
  seed?: number
  onDone?: () => void
}

let bursts = 0
const layers = new WeakMap<Element, HTMLElement>()

function layerFor(host: HTMLElement): HTMLElement {
  const known = layers.get(host)
  if (known?.isConnected) return known
  const layer = document.createElement("div")
  layer.setAttribute("data-slot", "confetti-layer")
  layer.setAttribute("aria-hidden", "true")
  const s = layer.style
  s.pointerEvents = "none"
  s.overflow = "hidden"
  s.position = host === document.body ? "fixed" : "absolute"
  s.inset = "0"
  s.zIndex = "var(--ll-z-splash)"
  host.appendChild(layer)
  layers.set(host, layer)
  return layer
}

const centreOf = (el: Element) => {
  const r = el.getBoundingClientRect()
  return { x: r.left + r.width / 2, y: r.top + r.height / 2 }
}

function confetti(options: ConfettiOptions & { container?: HTMLElement | null } = {}): () => void {
  if (typeof document === "undefined") return () => {}
  const host = options.container ?? document.body
  if (motionIsOff(host)) return () => {}
  const layer = layerFor(host)
  const box = layer.getBoundingClientRect()
  const at = options.origin
  const o = at && "getBoundingClientRect" in at ? centreOf(at) : at && "clientX" in at ? { x: at.clientX, y: at.clientY } : at && "x" in at ? at : { x: box.left + box.width / 2, y: box.top + box.height / 2 }
  const ox = o.x - box.left, oy = o.y - box.top
  const duration = options.duration ?? 2600
  const flights = simulate(
    {
      count: Math.min(400, Math.max(0, Math.round(options.count ?? 70))),
      spread: options.spread ?? 70,
      angle: options.angle ?? 90,
      velocity: options.velocity ?? 1100,
      gravity: options.gravity ?? 520,
      drift: options.drift ?? 0,
      duration,
      seed: options.seed ?? ++bursts,
    },
    options.shapes ?? CONFETTI_KINDS,
    options.colors ?? CONFETTI_COLORS,
  )
  const scalar = options.scalar ?? 1
  const live = new Set<Animation>()
  const pieces: Element[] = []
  const done = (el: Element) => {
    el.remove()
    if (!layer.childElementCount) layer.remove()
  }
  let over = false
  const end = () => {
    if (over) return
    over = true
    live.clear()
    pieces.length = 0
    options.onDone?.()
  }
  for (const f of flights) {
    const p = confettiPiece(f.kind, f.color, f.variant)
    const k = f.scale * scalar
    const wrap = document.createElement("div")
    wrap.innerHTML = `<svg aria-hidden="true" focusable="false" viewBox="0 0 ${p.w} ${p.h}" width="${(p.w * k).toFixed(1)}" height="${(p.h * k).toFixed(1)}" style="position:absolute;left:${(-p.w * k / 2).toFixed(1)}px;top:${(-p.h * k / 2).toFixed(1)}px;will-change:transform,opacity;overflow:visible">${p.svg}</svg>`
    const el = wrap.firstElementChild as SVGElement
    layer.appendChild(el)
    pieces.push(el)
    if (typeof el.animate !== "function") {
      done(el)
      continue
    }
    const anim = el.animate(
      f.frames.map((fr) => ({
        transform: `translate(${(ox + fr.x).toFixed(1)}px, ${(oy + fr.y).toFixed(1)}px) rotate(${fr.rot.toFixed(0)}deg) scale(1, ${fr.flip.toFixed(2)})`,
        opacity: fr.opacity,
      })),
      { duration: (f.frames.length - 1) * STEP_MS, easing: "linear", fill: "forwards" },
    )
    live.add(anim)
    anim.onfinish = () => {
      live.delete(anim)
      done(el)
      if (!live.size) end()
    }
  }
  if (!live.size) end()
  return () => {
    for (const a of live) a.cancel()
    for (const el of pieces) done(el)
    end()
  }
}

interface ConfettiHandle {
  burst(options?: ConfettiOptions): () => void
}

type ConfettiProps = Omit<React.ComponentProps<"div">, "children"> &
  ConfettiOptions & {
    active?: boolean
    burstKey?: number | string
    apiRef?: React.Ref<ConfettiHandle>
  }

function Confetti({ className, active, burstKey, apiRef, origin, count, spread, angle, velocity, gravity, drift, duration, colors, shapes, scalar, seed, onDone, ref, ...props }: ConfettiProps) {
  const el = React.useRef<HTMLDivElement | null>(null)
  const opts = { origin, count, spread, angle, velocity, gravity, drift, duration, colors, shapes, scalar, seed, onDone }
  const latest = React.useRef(opts)
  latest.current = opts
  const flying = React.useRef(new Set<() => void>())
  const throwIt = React.useCallback((extra?: ConfettiOptions) => {
    const merged = { ...latest.current, ...extra }
    let over = false
    let stop: () => void = () => {}
    stop = confetti({
      ...merged,
      container: el.current,
      onDone: () => {
        over = true
        flying.current.delete(stop)
        merged.onDone?.()
      },
    })
    if (!over) flying.current.add(stop)
    return stop
  }, [])
  React.useImperativeHandle(apiRef, () => ({ burst: throwIt }), [throwIt])
  React.useEffect(() => {
    if (active) throwIt()
  }, [active, throwIt])
  const key = React.useRef(burstKey)
  React.useEffect(() => {
    if (key.current !== burstKey) {
      key.current = burstKey
      throwIt()
    }
  }, [burstKey, throwIt])
  React.useEffect(() => {
    const set = flying.current
    return () => {
      for (const stop of [...set]) stop()
      set.clear()
    }
  }, [])
  return (
    <div
      data-slot="confetti"
      aria-hidden="true"
      ref={useMergedRef<HTMLDivElement>(el, ref)}
      className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)}
      {...props}
    />
  )
}

type ConfettiTriggerProps = React.ComponentProps<"button"> & ConfettiOptions & { asChild?: boolean }

function ConfettiTrigger({ asChild = false, onClick, origin, count, spread, angle, velocity, gravity, drift, duration, colors, shapes, scalar, seed, onDone, ...props }: ConfettiTriggerProps) {
  const Comp = asChild ? Slot.Root : "button"
  return (
    <Comp
      data-slot="confetti-trigger"
      type={asChild ? undefined : "button"}
      onClick={(e: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(e)
        if (!e.defaultPrevented) confetti({ origin: origin ?? e.currentTarget, count, spread, angle, velocity, gravity, drift, duration, colors, shapes, scalar, seed, onDone })
      }}
      {...props}
    />
  )
}

function useConfetti(defaults: ConfettiOptions = {}): (options?: ConfettiOptions) => () => void {
  const latest = React.useRef(defaults)
  latest.current = defaults
  return React.useCallback((options?: ConfettiOptions) => confetti({ ...latest.current, ...options }), [])
}

export { confetti, Confetti, ConfettiTrigger, useConfetti }
export type { ConfettiOptions, ConfettiProps, ConfettiHandle, ConfettiTriggerProps, ConfettiColor, ConfettiKind }

import { Ink } from '@/lib/ink/builder'
import { blobFill } from '@/lib/ink/fills'
import { ellipsePoly, polyPath, roundRectPoly } from '@/lib/ink/geom'
import type { PaintKey } from '@/lib/ink/paint'
import { clamp, makeRng, type Rng } from '@/lib/ink/rng'
import { box } from '@/lib/ink/shapes'
import type { Pt } from '@/lib/ink/types'

export const CONFETTI_KINDS = ['strip', 'dot', 'star', 'triangle', 'curl', 'scrap'] as const
export type ConfettiKind = (typeof CONFETTI_KINDS)[number]
export const CONFETTI_COLORS = ['tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum'] as const satisfies readonly PaintKey[]
export type ConfettiColor = (typeof CONFETTI_COLORS)[number]

export interface ConfettiPiece {
  svg: string
  w: number
  h: number
}

const cache = new Map<string, ConfettiPiece>()

const outline = (ink: Ink, x: number, y: number, w: number, h: number, corner = 1) =>
  box(ink, x, y, w, h, { pen: 'ink.fine', corner, style: 'loop', stubs: false, ghost: false, opts: { width: 0.55, alpha: 0.6 } })

export function confettiPiece(kind: ConfettiKind, color: PaintKey, variant = 0): ConfettiPiece {
  const key = `${kind}|${color}|${variant}`
  const hit = cache.get(key)
  if (hit) return hit
  const ink = new Ink(`confetti|${key}`, { grain: false })
  const fill = (poly: Pt[], alpha = 0.95, mis = 0.55) => blobFill(ink, poly, color, { alpha, mis, rough: 0.35, material: 'top' })
  let w = 16, h = 16
  const printed = (pts: Pt[]) => {
    ink.flat('top', polyPath(pts.map((p): Pt => [p[0] + 0.55, p[1] + 0.4]), 10), color, 0.95)
    ink.flat('top', polyPath(pts, 10), 'ink', 0.6, { stroke: 'ink', sw: 0.6 })
  }
  ink.layer('rest', () => {
    switch (kind) {
      case 'strip': {
        w = 9; h = 17
        fill(roundRectPoly(1.5, 1.5, 6, 14, 0.8))
        ink.flat('top', 'M4.5 2.5V14.5H7.5V2.5Z', 'ink', 0.13)
        outline(ink, 1.5, 1.5, 6, 14)
        break
      }
      case 'dot': {
        w = 14; h = 14
        fill(ellipsePoly(7, 7, 4.8, 4.6, 14))
        ink.flat('top', 'M9.6 5.2a1.5 1.5 0 1 1-.01 0Z', 'photo', 0.55)
        break
      }
      case 'star': {
        w = 20; h = 20
        const r = makeRng(`star${variant}`)
        const pts: Pt[] = []
        for (let i = 0; i < 10; i++) {
          const a = -Math.PI / 2 + (i * Math.PI) / 5 + r.gauss(0, 0.04)
          const rad = (i % 2 ? 4.4 : 8.8) * (1 + r.gauss(0, 0.05))
          pts.push([10 + Math.cos(a) * rad, 10.4 + Math.sin(a) * rad])
        }
        printed(pts)
        break
      }
      case 'triangle': {
        w = 16; h = 15
        printed([[8, 1.4], [14.8, 13.4], [1.3, 13]])
        break
      }
      case 'curl': {
        w = 26; h = 14
        const pts: Pt[] = []
        for (let i = 0; i <= 14; i++) pts.push([2 + i * 1.65, 7 + Math.sin(i * 0.9 + variant) * 4.2])
        ink.stroke(pts, 'ink', { color, width: 1.35, wobble: 0.3, start: 'soft', end: 'soft' })
        break
      }
      case 'scrap': {
        w = 16; h = 16
        const r: Rng = makeRng(`scrap${variant}`)
        const pts: Pt[] = []
        const n = 6 + (variant % 2)
        for (let i = 0; i < n; i++) {
          const a = (i / n) * Math.PI * 2 + r.gauss(0, 0.2)
          const rad = 4.6 + r() * 3.4
          pts.push([8 + Math.cos(a) * rad, 8 + Math.sin(a) * rad])
        }
        fill(pts, 0.95, 0.6)
        break
      }
    }
  })
  const res = ink.toSvg({ w, h, pad: 1 })
  const out: ConfettiPiece = { svg: res.svg, w, h }
  cache.set(key, out)
  return out
}

export interface FlightOptions {
  count: number
  spread: number
  angle: number
  velocity: number
  gravity: number
  drift: number
  duration: number
  seed: number
}

export interface Flight {
  kind: ConfettiKind
  color: ConfettiColor
  variant: number
  frames: Array<{ x: number; y: number; rot: number; flip: number; opacity: number }>
  scale: number
}

export const STEP_MS = 50

export function simulate(o: FlightOptions, kinds: readonly ConfettiKind[] = CONFETTI_KINDS, colors: readonly ConfettiColor[] = CONFETTI_COLORS): Flight[] {
  const rng = makeRng(`flight|${o.seed}`)
  const dt = STEP_MS / 1000
  const steps = Math.max(2, Math.round(o.duration / STEP_MS))
  const out: Flight[] = []
  for (let i = 0; i < o.count; i++) {
    const r = rng.fork(i)
    const a = ((o.angle + (r() - 0.5) * o.spread) * Math.PI) / 180
    const speed = o.velocity * (0.35 + 0.65 * Math.sqrt(r()))
    let vx = Math.cos(a) * speed, vy = -Math.sin(a) * speed
    const drag = 2.6 + r() * 1.2
    const sway = 10 + r() * 22, swayW = 3.5 + r() * 3, swayP = r() * 6.28
    const spin = (r() - 0.5) * 900, flipW = 4 + r() * 6, flipP = r() * 6.28
    let x = 0, y = 0
    const frames: Flight['frames'] = []
    for (let s = 0; s <= steps; s++) {
      const t = s * dt
      const p = s / steps
      frames.push({
        x: x + Math.sin(t * swayW + swayP) * sway * clamp(t * 1.5, 0, 1),
        y,
        rot: spin * t * Math.exp(-t * 0.6),
        flip: Math.cos(flipP + flipW * t),
        opacity: p < 0.72 ? 1 : Math.max(0, 1 - (p - 0.72) / 0.28),
      })
      vx += (o.drift - drag * vx) * dt
      vy += (o.gravity - drag * vy) * dt
      x += vx * dt
      y += vy * dt
    }
    out.push({ kind: kinds[Math.floor(r() * kinds.length)], color: colors[Math.floor(r() * colors.length)], variant: Math.floor(r() * 3), frames, scale: 0.85 + r() * 0.5 })
  }
  return out
}

